1	// Registry lookups. The tables live in registry/*.csv; this module reads the generated copy.
2	import { TABLES } from "@portside/dispatch/generated/registry.mjs";
3	import { normalizeCode } from "@portside/dispatch/util.mjs";
4	
5	function row(table, code) {
6	  const found = TABLES[table][normalizeCode(code)];
7	  if (!found) throw new Error(`unknown ${table} code: ${code}`);
8	  return { ...found };
9	}
10	
11	export function port(code) {
12	  return row("ports", code);
13	}
14	
15	export function vesselClass(code) {
16	  return row("vessels", code);
17	}
18
